# Do not edit: change the source and run the script again.
"""Zet de uitkomst van de Limescape-agent om naar het uitvoercontract van fase A."""

import re

SLEUTEL = "_eval"  # achtervoegsel van de node-sleutels in de eval-agent


# Standaardteksten van 'Dossier inlezen' voor een veld dat het zaaksysteem niet kent.
ONBEKEND = re.compile(r"^\s*(niet beschikbaar.*|geen .*geregistreerd.*|nog niet afgesloten)?\s*$", re.IGNORECASE)


def _leeg_is_none(tekst):
    return tekst.strip() if isinstance(tekst, str) and tekst.strip() else None


def naar_contract(uitkomst: dict, item) -> dict:
    """Zet de uitkomst van de agent om naar het uitvoercontract van fase A.

    Bronverwijzingen (bron_document) worden een document_id uit de dataset: de agent noemt het stuk
    met zijn id of zijn titel. Wat niet te herleiden is blijft staan zoals de agent het gaf, zodat
    de evaluator a_bron_bestaat het ziet. Het zaakoverzicht (sectie 1) komt zoals 'Dossier inlezen' het
    opbouwt uit de zaakgegevens; wat het zaaksysteem niet kent ('niet beschikbaar', 'geen ... geregistreerd') wordt None.
    """
    ids = {d["id"] for d in item.input["documenten"]}
    per_titel = {d["naam"].strip().lower(): d["id"] for d in item.input["documenten"]}

    def doc(verwijzing) -> str:
        v = (verwijzing or "").strip()
        if v in ids:
            return v
        return per_titel.get(v.lower()) or next((i for i in ids if v.startswith(i)), v)

    def node(naam):
        return uitkomst.get(naam + SLEUTEL) or {}

    dossier = uitkomst.get("dossier_inlezen" + SLEUTEL) or {}
    rollen = {doc(r.get("document_id")): r for r in node("documentrollen_bepalen").get("documenten") or []}
    documenten = [
        {"document_id": s["id"], "naam": s["titel"],
         "datum": _leeg_is_none(rollen.get(s["id"], {}).get("datum_iso") or rollen.get(s["id"], {}).get("datum_document")),
         "status": None, "type": _leeg_is_none(rollen.get(s["id"], {}).get("rol"))}
        for s in dossier.get("stukken") or []
    ]

    pb = node("primair_besluit_extraheren")
    pb_doc = doc(pb.get("bron_document")) if pb.get("gevonden") else None
    primair_besluit = {
        "document_id": pb_doc or None,
        "besloten": _leeg_is_none((pb.get("wat_is_besloten") or {}).get("samenvatting")),
        "aanleiding": _leeg_is_none((pb.get("aanleiding_of_overtreding") or {}).get("samenvatting")),
        "genoemde_grondslagen": [{"tekst": g["grondslag"], "document_id": pb_doc or ""} for g in pb.get("genoemde_grondslagen") or []],
        "bedragen": [{"tekst": f"{b['bedrag']} ({b['betekenis']})" if b.get("betekenis") else b["bedrag"], "document_id": pb_doc or ""}
                     for b in pb.get("bedragen") or []],
        "datums": [{"tekst": f"{d['datum_of_termijn']} ({d['betekenis']})" if d.get("betekenis") else d["datum_of_termijn"],
                    "document_id": pb_doc or ""} for d in pb.get("datums_en_termijnen") or []],
    }

    bz = node("bezwaargronden_extraheren")
    bz_doc = doc(bz.get("bron_document"))
    bezwaarmaker = _leeg_is_none((bz.get("bezwaarmaker") or {}).get("naam"))
    bezwaargronden = [{"tekst": g["grond"], "actor": bezwaarmaker, "document_id": bz_doc} for g in bz.get("gronden") or []]

    fs = node("feiten_en_standpunten_extraheren")
    feiten = [{"tekst": f["feit"], "document_id": doc(f.get("bron_document"))} for f in fs.get("feiten") or []]
    partijstandpunten = [{"tekst": p["standpunt"], "actor": _leeg_is_none(p.get("actor")), "document_id": doc(p.get("bron_document"))}
                         for p in fs.get("partijstandpunten") or []]

    tijdlijn = [{"datum": _leeg_is_none(g.get("datum")) or _leeg_is_none(g.get("datum_weergave")),
                 "gebeurtenis": g["gebeurtenis"], "document_id": doc(g.get("bron_document"))}
                for g in node("tijdlijn_opstellen").get("gebeurtenissen") or []]

    zaakoverzicht = {k: None if ONBEKEND.match(str(v or "")) else str(v)
                     for k, v in (dossier.get("zaakoverzicht") or {}).items() if k != "zaak_url"}
    return {"zaakoverzicht": zaakoverzicht, "documenten": documenten, "primair_besluit": primair_besluit,
            "bezwaargronden": bezwaargronden, "feiten": feiten, "partijstandpunten": partijstandpunten,
            "tijdlijn": tijdlijn}
